#ifdef __unix__

#include "input/linux/linuxinputmanager.h"
#include "input/linux/keymap.h"

namespace InputManager
{
    // Defaults match the release config.ini generated by server/release.bat,
    // so the server behaves sanely even when no config.ini is found next to
    // the executable (with 1, touchpad movement truncates to ~zero pixels).
    int MOVE_SENSITIVITY = 10;
    int SCROLL_SENSITIVITY = 3;

    Linux::Linux()
    {
        fd = open("/dev/uinput", O_WRONLY | O_NONBLOCK);
        if (fd < 0) {
            std::cerr << "[ERROR] Could not open /dev/uinput. Are you root? " 
                    << strerror(errno) << std::endl;
            return; 
        }

        ioctl(fd, UI_SET_EVBIT, EV_KEY);
        
        ioctl(fd, UI_SET_KEYBIT, BTN_LEFT);
        ioctl(fd, UI_SET_KEYBIT, BTN_RIGHT);
        ioctl(fd, UI_SET_KEYBIT, BTN_MIDDLE);

        for(const auto& [hid, code] : KEYMAP) {
            ioctl(fd, UI_SET_KEYBIT, code);
        }

        for(const auto& [bit, code] : MEDIAMAP) {
            ioctl(fd, UI_SET_KEYBIT, code);
        }

        for(const auto& [bit, code] : MODMAP) {
            ioctl(fd, UI_SET_KEYBIT, code);
        }

        ioctl(fd, UI_SET_EVBIT, EV_REL);
        ioctl(fd, UI_SET_RELBIT, REL_X);
        ioctl(fd, UI_SET_RELBIT, REL_Y);
        ioctl(fd, UI_SET_RELBIT, REL_WHEEL);
        ioctl(fd, UI_SET_RELBIT, REL_HWHEEL);

        ioctl(fd, UI_SET_EVBIT, EV_SYN);

        memset(&usetup, 0, sizeof(usetup));
        usetup.id.bustype = BUS_USB;
        usetup.id.vendor  = 0x1234; 
        usetup.id.product = 0x5678;
        strncpy(usetup.name, "Mousedroid", UINPUT_MAX_NAME_SIZE);

        if (ioctl(fd, UI_DEV_SETUP, &usetup) < 0) {
            std::cerr << "[ERROR] UI_DEV_SETUP failed." << std::endl;
        }
        if (ioctl(fd, UI_DEV_CREATE) < 0) {
            std::cerr << "[ERROR] UI_DEV_CREATE failed." << std::endl;
        }

        // Give the OS a moment to register the new HID device in the input stack
        usleep(100000);
    }

    void Linux::emit(int fd, int type, int code, int val) const
    {
        input_event ie;

        ie.type = type;
        ie.code = code;
        ie.value = val;
        ie.time.tv_sec = 0;
        ie.time.tv_usec = 0;

        write(fd, &ie, sizeof(ie));
    }

    void Linux::click() const
    {
        emit(fd, EV_KEY, BTN_LEFT, 1);
        emit(fd, EV_SYN, SYN_REPORT, 0);
        emit(fd, EV_KEY, BTN_LEFT, 0);
        emit(fd, EV_SYN, SYN_REPORT, 0);
    }

    void Linux::right_click() const
    {
        emit(fd, EV_KEY, BTN_RIGHT, 1);
        emit(fd, EV_SYN, SYN_REPORT, 0);
        emit(fd, EV_KEY, BTN_RIGHT, 0);
        emit(fd, EV_SYN, SYN_REPORT, 0);
    }

    void Linux::move(int dx, int dy) const
    {
        emit(fd, EV_REL, REL_X, (int)(MOVE_SENSITIVITY / 10.0 * dx));
        emit(fd, EV_REL, REL_Y, (int)(MOVE_SENSITIVITY / 10.0 * dy));
        emit(fd, EV_SYN, SYN_REPORT, 0);
    }

    void Linux::scroll(int scroll_amount) const
    {
        emit(fd, EV_KEY, KEY_LEFTSHIFT, 1);
        emit(fd, EV_SYN, SYN_REPORT, 0);

        emit(fd, EV_REL, REL_WHEEL, (int)((scroll_amount * (SCROLL_SENSITIVITY / 10.0))));
        emit(fd, EV_SYN, SYN_REPORT, 0);
        
        emit(fd, EV_KEY, KEY_LEFTSHIFT, 0);
        emit(fd, EV_SYN, SYN_REPORT, 0);
    }

    void Linux::scroll_h(int scroll_amount) const
    {
        emit(fd, EV_REL, REL_WHEEL, (int)((scroll_amount * (SCROLL_SENSITIVITY / 10.0))));
        emit(fd, EV_SYN, SYN_REPORT, 0);
    }

    void Linux::down() const
    {
        emit(fd, EV_KEY, BTN_LEFT, 1);
        emit(fd, EV_SYN, SYN_REPORT, 0);
    }

    void Linux::up() const 
    {
        emit(fd, EV_KEY, BTN_LEFT, 0);
        emit(fd, EV_SYN, SYN_REPORT, 0);
    }

    void Linux::send_key(uint8_t keycode, uint8_t modifier) const
    {
        // Extract modifier keys from the bitmask and add the to the input array
        for(const auto& mod : MODMAP)
        {
            if(modifier & mod.first)
            {
                emit(fd, EV_KEY, mod.second, 1);
            }
        }

        auto it = KEYMAP.find(keycode);
        if(it != KEYMAP.end())
        {
            emit(fd, EV_KEY, it->second, 1);
            emit(fd, EV_SYN, SYN_REPORT, 0);
            emit(fd, EV_KEY, it->second, 0);
        }

        // Release modifier keys in reverse order
        for (auto it_mod = MODMAP.rbegin(); it_mod != MODMAP.rend(); ++it_mod) 
        {
            if (modifier & it_mod->first) 
            {
                emit(fd, EV_KEY, it_mod->second, 0);
            }
        }

        emit(fd, EV_SYN, SYN_REPORT, 0);
    }

    void Linux::zoom(int scale) const
    {
        emit(fd, EV_KEY, KEY_LEFTCTRL, 1);
        emit(fd, EV_SYN, SYN_REPORT, 0);

        emit(fd, EV_REL, REL_WHEEL, scale);
        emit(fd, EV_SYN, SYN_REPORT, 0);
        
        emit(fd, EV_KEY, KEY_LEFTCTRL, 0);
        emit(fd, EV_SYN, SYN_REPORT, 0);
    }

    void Linux::media(uint8_t action) const
    {
        emit(fd, EV_KEY, MEDIAMAP.at(action), 1);
        emit(fd, EV_SYN, SYN_REPORT, 0);

        emit(fd, EV_KEY, MEDIAMAP.at(action), 0);
        emit(fd, EV_SYN, SYN_REPORT, 0);
    }

    void Linux::send_text(const char* text, size_t length) const
    {
        // uinput injects raw key codes, so only ASCII text that maps to key
        // codes can be typed; anything else is skipped. Linux key codes are
        // positional (not alphabetical), hence the lookup table.
        static const int LETTER_KEYCODES[26] = {
            KEY_A, KEY_B, KEY_C, KEY_D, KEY_E, KEY_F, KEY_G,
            KEY_H, KEY_I, KEY_J, KEY_K, KEY_L, KEY_M, KEY_N,
            KEY_O, KEY_P, KEY_Q, KEY_R, KEY_S, KEY_T, KEY_U,
            KEY_V, KEY_W, KEY_X, KEY_Y, KEY_Z
        };

        for (size_t i = 0; i < length; i++) {
            unsigned char c = text[i];
            int code = 0;
            bool shift = false;

            if (c >= 'a' && c <= 'z') {
                code = LETTER_KEYCODES[c - 'a'];
            } else if (c >= 'A' && c <= 'Z') {
                code = LETTER_KEYCODES[c - 'A'];
                shift = true;
            } else if (c >= '1' && c <= '9') {
                code = KEY_1 + (c - '1');
            } else if (c == '0') {
                code = KEY_0;
            } else {
                switch (c) {
                    case ' ': code = KEY_SPACE; break;
                    case '\n': code = KEY_ENTER; break;
                    case '\t': code = KEY_TAB; break;
                    case '-': code = KEY_MINUS; break;
                    case '_': code = KEY_MINUS; shift = true; break;
                    case '=': code = KEY_EQUAL; break;
                    case '+': code = KEY_EQUAL; shift = true; break;
                    case '[': code = KEY_LEFTBRACE; break;
                    case '{': code = KEY_LEFTBRACE; shift = true; break;
                    case ']': code = KEY_RIGHTBRACE; break;
                    case '}': code = KEY_RIGHTBRACE; shift = true; break;
                    case '\\': code = KEY_BACKSLASH; break;
                    case '|': code = KEY_BACKSLASH; shift = true; break;
                    case ';': code = KEY_SEMICOLON; break;
                    case ':': code = KEY_SEMICOLON; shift = true; break;
                    case '\'': code = KEY_APOSTROPHE; break;
                    case '"': code = KEY_APOSTROPHE; shift = true; break;
                    case '`': code = KEY_GRAVE; break;
                    case '~': code = KEY_GRAVE; shift = true; break;
                    case ',': code = KEY_COMMA; break;
                    case '<': code = KEY_COMMA; shift = true; break;
                    case '.': code = KEY_DOT; break;
                    case '>': code = KEY_DOT; shift = true; break;
                    case '/': code = KEY_SLASH; break;
                    case '?': code = KEY_SLASH; shift = true; break;
                    case '!': code = KEY_1; shift = true; break;
                    case '@': code = KEY_2; shift = true; break;
                    case '#': code = KEY_3; shift = true; break;
                    case '$': code = KEY_4; shift = true; break;
                    case '%': code = KEY_5; shift = true; break;
                    case '^': code = KEY_6; shift = true; break;
                    case '&': code = KEY_7; shift = true; break;
                    case '*': code = KEY_8; shift = true; break;
                    case '(': code = KEY_9; shift = true; break;
                    case ')': code = KEY_0; shift = true; break;
                    default: break;
                }
            }

            if (code == 0) {
                continue;
            }

            if (shift) {
                emit(fd, EV_KEY, KEY_LEFTSHIFT, 1);
            }
            emit(fd, EV_KEY, code, 1);
            emit(fd, EV_SYN, SYN_REPORT, 0);
            emit(fd, EV_KEY, code, 0);
            if (shift) {
                emit(fd, EV_KEY, KEY_LEFTSHIFT, 0);
            }
            emit(fd, EV_SYN, SYN_REPORT, 0);
        }
    }
}

#endif